package localchat;
import java.nio.file.*;import java.util.*;import java.util.concurrent.atomic.AtomicInteger;
public final class ToolProtocolTest {
 static int checks;static void check(boolean b,String why){checks++;if(!b)throw new AssertionError(why);}
 static final String BAD="<think><minimax:tool_call><invoke name=\"run_command\"><parameter name=\"command\">echo not executed</parameter></invoke></minimax:tool_call>";
 static Tools tools(Path root){return new Tools(new Tools.Context(root,root.resolve("skills"),root.resolve("rules.md"),root.resolve("settings.properties"),Map.of(),null,new Mcp(),PathMap.none(),true,EnumSet.allOf(Tools.Access.class),(a,b)->Tools.Decision.NO),List.of());}
 static Agent.Ui ui(AtomicInteger count){return new Agent.Ui(){public void text(String s){}public void step(){}public void toolStarted(ChatClient.ToolCall c){count.incrementAndGet();}public void toolFinished(ChatClient.ToolCall c,Tools.Result r){}};}
 public static void main(String[] args)throws Exception{
  Path home=Files.createTempDirectory(Files.createDirectories(Path.of(System.getProperty("localchat.home"))),"run-");Files.writeString(home.resolve("fixture.txt"),"verified fixture");check(ToolProtocol.malformed(BAD),"reported MiniMax protocol debris detected");check(!ToolProtocol.malformed("Example: `<minimax:tool_call>`")&&!ToolProtocol.malformed("```xml\n"+BAD+"\n```"),"quoted examples are not treated as calls");
  String nativeCall=Json.write(Json.obj("choices",List.of(Json.obj("message",Json.obj("content","","tool_calls",List.of(Json.obj("id","native","type","function","function",Json.obj("name","read_file","arguments",Json.write(Json.obj("path","fixture.txt"))))))))));
  try(var server=new FeatureTest.Server(FeatureTest.json(FeatureTest.answer(BAD,5,3)),FeatureTest.json(nativeCall),FeatureTest.json(FeatureTest.answer("Final checked",8,3)))){var a=new Agent(tools(home));AtomicInteger executed=new AtomicInteger();a.run(Provider.CUSTOM,server.url(),"","arbitrary-model","fixture","system",List.of(ChatClient.Message.user("Read fixture")),false,ui(executed));check(server.requests.size()==3&&executed.get()==1,"malformed XML never executes; corrected native call executes exactly once");check(Json.write(server.requests.get(1)).contains("No text/XML request was executed"),"repair instruction distinguishes unexecuted markup from prior confirmed actions");check(a.collect("","fixture").stream().anyMatch(m->m.content.equals("Final checked")),"normal final response preserved");}
  try(var server=new FeatureTest.Server(FeatureTest.json(FeatureTest.answer(BAD,5,3)),FeatureTest.json(FeatureTest.answer(BAD,5,3)),FeatureTest.json(FeatureTest.answer(BAD,5,3)))){AtomicInteger executed=new AtomicInteger();try{new Agent(tools(home)).run(Provider.CUSTOM,server.url(),"","arbitrary-model","fixture","system",List.of(ChatClient.Message.user("Read fixture")),false,ui(executed));throw new AssertionError("unbounded repair");}catch(java.io.IOException expected){check(server.requests.size()==3&&executed.get()==0,"protocol recovery limited to two retries with no XML execution");}}
  try(var server=new FeatureTest.Server(FeatureTest.json(FeatureTest.answer(BAD,5,3)))){new Agent(null).run(Provider.CUSTOM,server.url(),"","arbitrary-model","fixture","system",List.of(ChatClient.Message.user("Explain markup")),false,ui(new AtomicInteger()));check(server.requests.size()==1,"Normal mode never receives MBS repair retries");}
  Tools.Result invalid=tools(home).execute(new ChatClient.ToolCall("python","run_command",Json.obj("command","python -c \"import os\nprint('not-run')\"","cwd",home.toString())));check(invalid.isError&&invalid.text.contains(".py"),"multiline Python -c rejected with actionable script guidance before execution");System.out.println("PASS: "+checks+" tool protocol checks");
 }
}
